const _ = require('lodash');
const constant = require('../lib/constant');

/**
 * set:
 * sadd key member [member ...]
 * scard key
 * sismember key member
 * smembers key
 * srem key member [member ...]
 */
module.exports = (common) => {
  const operations = {
    * sadd(key, ...member) {
      const members = common.getFieldToArray(member);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || members === null) {
        return false;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.SET, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        let set;
        if (objVer === null || objVer.value === null || !_.isArray(objVer.value) || objVer.value.length === 0) {
          set = new Set();
        } else {
          set = new Set(objVer.value);
        }
        members.forEach(member => {
          if (_.isObject(member)) {
            for (const v of set.keys()) {
              if (_.isEqual(v, member)) {
                set.delete(v);
                break;
              }
            }
          }
          set.add(member);
        });
        const ret = yield common.setStringEx(key, common.toStringWithType(Array.from(set), constant.TYPE.SET), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return true;
        }
      }
      /* istanbul ignore next */
      return false;
    },

    * scard(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return 0;
      }
      const set = yield operations.smembers(key, forceMaster);
      if (set === undefined) {
        return undefined;
      }
      return _.isSet(set) ? set.size : 0;
    },

    * sismember(key, member, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || member === null || member === undefined) {
        return false;
      }
      const set = yield operations.smembers(key, forceMaster);
      if (set === undefined) {
        return undefined;
      }
      if (!_.isObject(member)) {
        return _.isSet(set) ? set.has(member) : false;
      }
      for (const v of set.keys()) {
        if (_.isEqual(v, member)) {
          return true;
        }
      }

      return false;
    },

    * smembers(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return new Set();
      }
      const set = yield common.getValue(key, constant.TYPE.SET, forceMaster);
      if (set === undefined) {
        return undefined;
      }
      /* istanbul ignore if */
      if (set === null) {
        return new Set();
      }
      return new Set(set);
    },

    * srem(key, ...member) {
      const members = common.getFieldToArray(member);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || members === null || !_.isArray(members) || members.length === 0) {
        return 0;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.SET, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        let set = null;
        /* istanbul ignore if */
        if (objVer === null || objVer.value === null || !_.isArray(objVer.value) || objVer.value.length === 0) {
          return 0;
        }
        set = new Set(objVer.value);

        let count = 0;
        members.forEach(member => {
          if (!_.isObject(member)) {
            if (set.delete(member)) {
              count++;
            }
          } else {
            for (const m of set.keys()) {
              if (_.isEqual(member, m)) {
                set.delete(m);
                count++;
              }
            }
          }
        });
        if (count) {
          const ret = yield common.setStringEx(key, common.toStringWithType(Array.from(set), constant.TYPE.SET), objVer.ver);
          if (ret === undefined) {
            return undefined;
          }
          if (ret) {
            return count;
          }
        }
      }
      return 0;
    },
  };
  return operations;
};
